				} });","import { createCustomElement } from '@servicenow/ui-core';
import snabbdom from '@servicenow/ui-renderer-snabbdom';
import styles from './styles.scss';

/* ------------------------------------------------------------------ *
 * x-soori-library-metric-card
 * A configurable KPI / metric card for ServiceNow Next Experience.
 *
 * Per SERVICENOW_CUSTOM_COMPONENT_DEV_RULES.md §0/§3.1/§5:
 * - Standard components, supplied by the instance (declared in
 * now-ui.json innerComponents, never imported here):
 * * now-card — container, border, radius, click + a11y
 * * now-icon — the tile icon (Horizon icon names only)
 * * now-highlighted-value — the trend pill
 * - DOCUMENTED EXCEPTIONS (owned markup, token-styled in styles.scss):
 * * the icon tile box (no design-system icon-tile primitive),
 * * the heading line and the large KPI value (no "big number"
 * component; now-heading renders a fixed heading scale).
 * ------------------------------------------------------------------ */

/* ---- Formatting helpers ---------------------------------------- */
const toNumber = (raw) => {
	if (raw === null || raw === undefined || raw === '') return NaN;
	if (typeof raw === 'number') return raw;
	const cleaned = String(raw).replace(/[^0-9.\-]/g, '');
	return cleaned === '' ? NaN : Number(cleaned);
};

const formatValue = ({ value, format, decimals, currencySymbol }) => {
	const num = toNumber(value);
	if (Number.isNaN(num)) return value === '' || value == null ? '—' : String(value);
	const places = Math.max(0, Number(decimals) || 0);
	const fixed = num.toLocaleString(undefined, { minimumFractionDigits: places, maximumFractionDigits: places });
	switch (format) {
		case 'percent': return `${fixed}%`;
		case 'currency': return `${currencySymbol || ''}${fixed}`;
		case 'number': return fixed;
		case 'none':
		default: return String(value);
	}
};

const resolveDirection = (direction, delta) => {
	if (direction && direction !== 'auto') return direction;
	if (Number.isNaN(delta) || delta === 0) return 'flat';
	return delta > 0 ? 'up' : 'down';
};

const resolveTone = (direction, positiveIsGood) => {
	if (direction === 'flat') return 'neutral';
	const isGood = direction === 'up' ? positiveIsGood : !positiveIsGood;
	return isGood ? 'good' : 'bad';
};

const ARROW = { up: '↑', down: '↓', flat: '→' };
/* Trend tone → now-highlighted-value colour. */
const TONE_COLOR = { good: 'positive', bad: 'critical', neutral: 'low' };
/* Icon tile tones — each maps to the theme's alert palette (styles.scss). */
const ICON_TONES = ['info', 'positive', 'warning', 'high', 'critical', 'moderate', 'low'];

/* ---- Trend (now-highlighted-value) ----------------------------- */
/* The pill and the caption are independent: "Show trend" off (or no numeric
 * Trend value) hides only the pill — the caption still shows, so a card can
 * read "2 · Card + phone" with no percentage at all. */
const Trend = ({ showTrend, trendValue, trendDirection, trendPeriod, trendPositiveIsGood, decimals }) => {
	const delta = toNumber(trendValue);
	const pill = showTrend !== false && !Number.isNaN(delta);
	const caption = trendPeriod == null ? '' : String(trendPeriod).trim();
	if (!pill && !caption) return null;
	let pillNode = null;
	if (pill) {
		const direction = resolveDirection(trendDirection, delta);
		const tone = resolveTone(direction, trendPositiveIsGood);
		const places = Math.max(0, Number(decimals) || 0);
		const magnitude = Math.abs(delta).toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: places });
		pillNode = (
			<now-highlighted-value
				label={`${ARROW[direction]} ${magnitude}%`}
				color={TONE_COLOR[tone]}
				variant="tertiary"
			/>
		);
	}
	return (
		<div className="mc-trend">
			{pillNode}
			{caption ? <span className="mc-trend-period">{caption}</span> : null}
		</div>
	);
};

/* ---- Root view ------------------------------------------------- */
const ROW_ALIGN = { top: 'flex-start', center: 'center', bottom: 'flex-end' };

const view = (state) => {
	const { heading, icon, iconTone, iconAlign, clickable } = state.properties;
	const tone = ICON_TONES.includes(iconTone) ? iconTone : 'info';
	/* An empty HTML attribute arrives as `true`; only a real name is an icon. */
	const iconName = typeof icon === 'string' ? icon.trim() : '';

	return (
		<now-card
			className="mc-card"
			interaction={clickable ? 'click' : 'none'}
			configAria={clickable ? { button: { 'aria-label': heading || 'Metric card' } } : undefined}
		>
			<div className="mc-row" style={{ alignItems: ROW_ALIGN[iconAlign] || ROW_ALIGN.center }}>
				{iconName ? (
					<div className={`mc-icon mc-tone--${tone}`} aria-hidden="true">
						<now-icon icon={iconName} size="lg" />
					</div>
				) : null}
				<div className="mc-body">
					{heading ? <div className="mc-heading">{heading}</div> : null}
					<div className="mc-value">{formatValue(state.properties)}</div>
					{Trend(state.properties)}
				</div>
			</div>
		</now-card>
	);
};

createCustomElement('x-soori-library-metric-card', {
	renderer: { type: snabbdom },
	view,
	styles,
	properties: {
		heading: { default: 'Submissions to Quote Ratio' },
		icon: { default: 'clipboard-outline' },
		iconTone: { default: 'info' },
		iconAlign: { default: 'center' },
		value: { default: '25' },
		format: { default: 'percent' },
		decimals: { default: 2 },
		currencySymbol: { default: '$' },
		showTrend: { default: true },
		/* EMPTY at runtime, deliberately. An unbound or empty binding reaches the
		 * component as unset, and the runtime default fills it — with '-4.2' that
		 * painted a fake "↓ 4.2%" on cards that had no trend data. The UI Builder
		 * default (now-ui.json) still shows the demo trend on a freshly dropped card. */
		trendValue: { default: '' },
		trendDirection: { default: 'auto' },
		trendPeriod: { default: 'MoM' },
		trendPositiveIsGood: { default: true },
		clickable: { default: false },
	},
	actionHandlers: {
		'NOW_CARD#CLICKED': ({ state, dispatch }) => {
			if (!state.properties.clickable) return;
			dispatch('METRIC_CARD_CLICKED', {
				heading: state.properties.heading,
				value: formatValue(state.properties),
			});
		},
	},
});
